import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import Header from './components/Header';
import Login from './pages/Login';
import Profile from './pages/Profile';
import EditProfile from './pages/EditProfile';       // добавлен
import Teachers from './pages/Teachers';
import Schedule from './pages/Schedule';
import Progress from './pages/Progress';
import Students from './pages/Students';
import AdminPanel from './pages/AdminPanel';
import PrivateRoute from './components/PrivateRoute';  // ← добавлен импорт
import 'bootstrap/dist/css/bootstrap.min.css';

function App() {
  const { isAuth } = useSelector(state => state.auth);

  return (
    <BrowserRouter>
      {isAuth && <Header />}
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/" element={<Navigate to={isAuth ? '/profile' : '/login'} />} />

        <Route path="/profile" element={
          <PrivateRoute><Profile /></PrivateRoute>
        } />
        <Route path="/profile/edit" element={
          <PrivateRoute><EditProfile /></PrivateRoute>
        } />
        <Route path="/teachers" element={
          <PrivateRoute><Teachers /></PrivateRoute>
        } />
        <Route path="/schedule" element={
          <PrivateRoute><Schedule /></PrivateRoute>
        } />
        <Route path="/progress" element={
          <PrivateRoute><Progress /></PrivateRoute>
        } />
        <Route path="/students" element={
          <PrivateRoute requiredRole="Директор"><Students /></PrivateRoute>
        } />
        <Route path="/admin" element={
          <PrivateRoute requiredRole="Директор"><AdminPanel /></PrivateRoute>
        } />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
